import{f as o,D as i,o as s,c as r,k as t,a as n,G as d,ar as l}from"./chunks/framework.HWAOx3Ef.js";const v=JSON.parse('{"title":"Verzicht auf Annotation von HttpStatus OK bei Controllern","description":"","frontmatter":{},"headers":[],"relativePath":"technik/adr/adr-keine-annotation-von-default-http-status-ok.md","filePath":"technik/adr/adr-keine-annotation-von-default-http-status-ok.md"}'),c={name:"technik/adr/adr-keine-annotation-von-default-http-status-ok.md"};function h(u,e,p,b,f,k){const a=i("adr-status");return s(),r("div",null,[e[0]||(e[0]=t("h1",{id:"verzicht-auf-annotation-von-httpstatus-ok-bei-controllern",tabindex:"-1"},[n("Verzicht auf Annotation von HttpStatus OK bei Controllern "),t("a",{class:"header-anchor",href:"#verzicht-auf-annotation-von-httpstatus-ok-bei-controllern","aria-label":'Permalink to "Verzicht auf Annotation von HttpStatus OK bei Controllern"'},"​")],-1)),e[1]||(e[1]=t("h2",{id:"status",tabindex:"-1"},[n("Status "),t("a",{class:"header-anchor",href:"#status","aria-label":'Permalink to "Status"'},"​")],-1)),d(a,{status:"accepted"}),e[2]||(e[2]=l('<h2 id="kontext" tabindex="-1">Kontext <a class="header-anchor" href="#kontext" aria-label="Permalink to &quot;Kontext&quot;">​</a></h2><p>Wir haben in den Controllern ein gemischtes Verhalten. Manchmal ist die Annotation<br><code>org.springframework.web.bind.annotation.ResponseStatus</code> mit dem Wert <code>HttpStatus.OK</code> gesetzt, und bei manchen Controllern<br> ist die Annotation wieder nicht vorhanden.</p><p>Die Annotation ist nicht erforderlich, wenn der Controller als Return-Typ keine <code>ResponseEntity</code> hat und den Status<br><code>OK</code> liefern soll, da dies in diesem Fall das Standardverhalten ist.</p><h2 id="entscheidung" tabindex="-1">Entscheidung <a class="header-anchor" href="#entscheidung" aria-label="Permalink to &quot;Entscheidung&quot;">​</a></h2><p>Wir wollen konsequent auf die Annotation mit dem Wert <code>HttpStatus.OK</code> verzichten, wenn sie nicht notwendig ist. Sollte sich das Verhalten ändern, stellen Integrationstests sicher, dass der erwartete <code>HttpStatus</code> geliefert wird. Dies betrifft sowohl die Methoden des Controllers als auch den Controller selbst.</p><p>Methoden mit dem Rückgabetyp <code>ResponseEntity</code> dürfen keine <code>ResponseStatus</code>-Annotation besitzen, da bei Verwendung von <code>ResponseEntity</code> die Statusinformationen durch die <code>ResponseEntity</code> überschrieben werden.</p><p>Mittels ArchUnit-Rules soll die Umsetzung des ADR sichergestellt werden.</p><h2 id="konsequenzen" tabindex="-1">Konsequenzen <a class="header-anchor" href="#konsequenzen" aria-label="Permalink to &quot;Konsequenzen&quot;">​</a></h2><h3 id="positiv" tabindex="-1">positiv <a class="header-anchor" href="#positiv" aria-label="Permalink to &quot;positiv&quot;">​</a></h3><ul><li>Wir haben einen einheitlichen Code.</li></ul><h3 id="negativ" tabindex="-1">negativ <a class="header-anchor" href="#negativ" aria-label="Permalink to &quot;negativ&quot;">​</a></h3><ul><li>Aufwand durch Anpassung des bestehenden Codes.</li></ul>',12))])}const g=o(c,[["render",h]]);export{v as __pageData,g as default};
